class TestKthBasic:
    """Basic correctness tests derived from the docstring spec."""

    def test_kth_single_element(self):
        """kth([x], 0) must return x (only element, k=0)."""
        assert kth([42], 0) == 42

    def test_kth_single_element_negative(self):
        """kth([-7], 0) must return -7."""
        assert kth([-7], 0) == -7

    def test_kth_two_elements_k0(self):
        """kth([a, b], 0) is the minimum of the two."""
        assert kth([5, 3], 0) == 3

    def test_kth_two_elements_k1(self):
        """kth([a, b], 1) is the maximum of the two."""
        assert kth([5, 3], 1) == 5

    def test_kth_sorted_ascending(self):
        """On an already sorted list, kth(arr, k) == arr[k]."""
        arr = [1, 2, 3, 4, 5]
        for k in range(len(arr)):
            assert kth(arr, k) == arr[k]

    def test_kth_sorted_descending(self):
        """On a descending list, kth(arr, k) == sorted(arr)[k]."""
        arr = [5, 4, 3, 2, 1]
        expected = sorted(arr)
        for k in range(len(arr)):
            assert kth(arr, k) == expected[k]

    def test_kth_matches_sorted_reference(self):
        """kth(arr, k) must equal sorted(arr)[k] for all valid k."""
        arr = [9, 1, 8, 2, 7, 3, 6, 4, 5, 0]
        expected = sorted(arr)
        for k in range(len(arr)):
            assert kth(arr, k) == expected[k]

    def test_kth_duplicates(self):
        """Duplicates must be handled: kth equals sorted(arr)[k]."""
        arr = [3, 3, 1, 1, 2, 2]
        expected = sorted(arr)
        for k in range(len(arr)):
            assert kth(arr, k) == expected[k]

    def test_kth_all_equal(self):
        """All-equal list: every k yields the same value."""
        arr = [7, 7, 7, 7]
        for k in range(len(arr)):
            assert kth(arr, k) == 7

    def test_kth_negative_values(self):
        """Negative ints are allowed; result equals sorted(arr)[k]."""
